param()
$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
$Version='1.1.105'
$TargetNotebookId='8d1eda83-cfe3-4487-b2bc-266a5be3465c'
$TargetUrl='https://notebook.google.com/notebook/'+$TargetNotebookId
$Port=9223
$Root=Join-Path $env:LOCALAPPDATA 'HomeDesignAutomationV7\LocalAgent'
New-Item -ItemType Directory -Force -Path $Root | Out-Null
function Tabs{$r=Invoke-WebRequest -UseBasicParsing -Uri ("http://127.0.0.1:$Port/json/list") -TimeoutSec 3;$o=$r.Content | ConvertFrom-Json;$a=@();if($o -is [System.Array]){foreach($x in $o){$a += $x}}elseif($null -ne $o){$a += $o};return $a}
function Recv($w,[int]$sec){$b=New-Object byte[] 65536;$m=New-Object IO.MemoryStream;$c=New-Object Threading.CancellationTokenSource;$c.CancelAfter([Math]::Max(1000,$sec*1000));try{do{$g=New-Object ArraySegment[byte] -ArgumentList @(,$b);$r=$w.ReceiveAsync($g,$c.Token).GetAwaiter().GetResult();if($r.MessageType -eq [System.Net.WebSockets.WebSocketMessageType]::Close){throw 'CDP_CLOSED'};$m.Write($b,0,$r.Count)}while(-not $r.EndOfMessage);return ([Text.Encoding]::UTF8.GetString($m.ToArray()) | ConvertFrom-Json)}finally{$c.Dispose();$m.Dispose()}}
function Send($w,[ref]$q,[string]$method,[hashtable]$params=@{}){$q.Value++;$id=$q.Value;$j=@{id=$id;method=$method;params=$params} | ConvertTo-Json -Depth 30 -Compress;$bb=[Text.Encoding]::UTF8.GetBytes($j);$g=New-Object ArraySegment[byte] -ArgumentList @(,$bb);$c=New-Object Threading.CancellationTokenSource;$c.CancelAfter(8000);try{[void]$w.SendAsync($g,[System.Net.WebSockets.WebSocketMessageType]::Text,$true,$c.Token).GetAwaiter().GetResult()}finally{$c.Dispose()};while($true){$z=Recv $w 8;if($z.id -eq $id){if($z.error){throw ('CDP_'+$method+':'+($z.error | ConvertTo-Json -Compress))};return $z.result}}}
function Eval($w,[ref]$q,[string]$e){$r=Send $w $q 'Runtime.evaluate' @{expression=$e;returnByValue=$true;awaitPromise=$true;userGesture=$true};return $r.result.value}
function Click($w,[ref]$q,[double]$x,[double]$y){[void](Send $w $q 'Input.dispatchMouseEvent' @{type='mouseMoved';x=$x;y=$y});[void](Send $w $q 'Input.dispatchMouseEvent' @{type='mousePressed';x=$x;y=$y;button='left';clickCount=1});Start-Sleep -Milliseconds 120;[void](Send $w $q 'Input.dispatchMouseEvent' @{type='mouseReleased';x=$x;y=$y;button='left';clickCount=1})}
function Connect([string]$wsUrl){$w=New-Object System.Net.WebSockets.ClientWebSocket;$c=New-Object Threading.CancellationTokenSource;$c.CancelAfter(8000);try{[void]$w.ConnectAsync([Uri]$wsUrl,$c.Token).GetAwaiter().GetResult()}finally{$c.Dispose()};return $w}
function FindCentral{$target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('MDBf7KSR7JWZ7JeQ7J207KCE7Yq4'));$my=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('64K0IOuTnOudvOydtOu4jA=='));foreach($d in @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)){$r=[string]$d.Root;if(-not $r){continue};foreach($c in @((Join-Path $r $target),(Join-Path $r ($my+'\'+$target)),(Join-Path $r ('My Drive\'+$target)),(Join-Path $r ('Google Drive\'+$target)))){if(Test-Path -LiteralPath $c -PathType Container){return $c}}};return ''}
function SaveCentral([string]$Name,$Object){try{$j=$Object | ConvertTo-Json -Depth 80;$j | Set-Content -LiteralPath (Join-Path $Root $Name) -Encoding UTF8;$c=FindCentral;if($c){$d=Join-Path $c 'Runtime_Readback';New-Item -ItemType Directory -Force -Path $d | Out-Null;$p=Join-Path $d $Name;$j | Set-Content -LiteralPath $p -Encoding UTF8;return $p}}catch{};return ''}
$probeJs="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};const body=document.body?.innerText||'';let exactCount=0;const countEls=[];for(const e of [...document.querySelectorAll('*')].filter(vis)){const s=String(e.innerText||e.textContent||'').replace(/\s+/g,' ').trim();let m=s.match(/^\uC18C\uC2A4\s*([0-9]+)\uAC1C$/i)||s.match(/^([0-9]+)\s*sources?$/i);if(m){const n=Number(m[1]);if(Number.isFinite(n)){exactCount=Math.max(exactCount,n);countEls.push(s)}}}const sourceLike=[...document.querySelectorAll('source-item,[data-testid*=source],[class*=source-item],mat-list-option,[role=option]')].filter(vis).map(e=>String(e.innerText||e.textContent||'').trim().slice(0,180));const empty=/\uC800\uC7A5\uB41C \uC18C\uC2A4\uAC00 \uC5EC\uAE30\uC5D0 \uD45C\uC2DC\uB429\uB2C8\uB2E4/.test(body);return {exactCount,countEls:[...new Set(countEls)].slice(0,20),sourceLikeCount:sourceLike.length,sourceLike:sourceLike.slice(0,30),empty,fastComplete:/Fast Research\s*\uC644\uB8CC/i.test(body),hasImport:/\uAC00\uC838\uC624\uAE30|\bimport\b/i.test(body),body:body.slice(0,14000)}})()"
$result=[ordered]@{ok=$false;action='AGENT_1.1.105_FAST_RESEARCH_IMPORT_ACTUAL_SOURCE_VERIFY';version=$Version;targetUrl=$TargetUrl;startedAt=(Get-Date).ToString('o');exactTab=$false;sourceTabClicked=$false;before=$null;importButton=$null;importClicked=$false;after=$null;actualSourceVerified=$false;normalChromeTouched=$false;bridgeChanged=$false;oauthChanged=$false;scopeChanged=$false;chatSubmitted=$false;studioSelected=$false;generateClicked=$false;downloadClicked=$false;stage='START';error='';centralPath=''}
$w=$null
try{$pages=@(Tabs | Where-Object{[string]$_.type -eq 'page'});$tab=$pages | Where-Object{[string]$_.url -eq $TargetUrl} | Select-Object -First 1;if(-not $tab){$tab=$pages | Where-Object{[string]$_.url -like 'https://notebook.google.com/*'} | Select-Object -First 1};if(-not $tab){throw 'NO_NOTEBOOKLM_PAGE'};$w=Connect ([string]$tab.webSocketDebuggerUrl);$q=0;[void](Send $w ([ref]$q) 'Runtime.enable' @{});[void](Send $w ([ref]$q) 'Page.enable' @{});[void](Send $w ([ref]$q) 'Page.bringToFront' @{});$u=[string](Eval $w ([ref]$q) 'location.href');if($u -ne $TargetUrl){[void](Send $w ([ref]$q) 'Page.navigate' @{url=$TargetUrl});Start-Sleep -Seconds 2};$u=[string](Eval $w ([ref]$q) 'location.href');if($u -ne $TargetUrl){throw 'EXACT_NOTEBOOK_NAVIGATION_FAILED'};$result.exactTab=$true;$x=Eval $w ([ref]$q) "(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};const a=[...document.querySelectorAll('[role=tab]')].filter(vis).filter(e=>String(e.innerText||e.textContent||'').trim().includes('\uCD9C\uCC98'));if(!a.length)return{ok:false};const r=a[0].getBoundingClientRect();return{ok:true,x:r.left+r.width/2,y:r.top+r.height/2,text:String(a[0].innerText||a[0].textContent||'').trim()}})()";if(-not $x.ok){throw 'SOURCE_TAB_NOT_FOUND'};Click $w ([ref]$q) ([double]$x.x) ([double]$x.y);$result.sourceTabClicked=$true;Start-Sleep -Seconds 1;$before=Eval $w ([ref]$q) $probeJs;$result.before=$before;if(([int]$before.exactCount -gt 0 -or ([int]$before.sourceLikeCount -gt 0 -and -not [bool]$before.empty))){$result.actualSourceVerified=$true;$result.after=$before;$result.ok=$true;$result.stage='ALREADY_HAS_SOURCES'}else{if(-not [bool]$before.fastComplete){throw 'FAST_RESEARCH_RESULTS_NOT_AVAILABLE'};$x=Eval $w ([ref]$q) "(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'&&!e.disabled};const txt=e=>String([e.innerText,e.textContent,e.getAttribute('aria-label'),e.getAttribute('title')].join(' ')).replace(/\s+/g,' ').trim();const a=[...document.querySelectorAll('button,[role=button],nb-button')].filter(vis).filter(e=>{const s=txt(e);return s==='\uAC00\uC838\uC624\uAE30'||/^import$/i.test(s)});return {ok:a.length===1,count:a.length,items:a.map(e=>txt(e).slice(0,120)),x:a.length===1?a[0].getBoundingClientRect().left+a[0].getBoundingClientRect().width/2:0,y:a.length===1?a[0].getBoundingClientRect().top+a[0].getBoundingClientRect().height/2:0}})()";$result.importButton=$x;if(-not $x.ok){throw ('IMPORT_BUTTON_NOT_UNIQUE count='+[string]$x.count)};Click $w ([ref]$q) ([double]$x.x) ([double]$x.y);$result.importClicked=$true;$deadline=(Get-Date).AddSeconds(120);do{Start-Sleep -Seconds 3;$after=Eval $w ([ref]$q) $probeJs;$result.after=$after;if(([int]$after.exactCount -gt 0 -or ([int]$after.sourceLikeCount -gt 0 -and -not [bool]$after.empty))){$result.actualSourceVerified=$true;break}}while((Get-Date) -lt $deadline);if(-not $result.actualSourceVerified){throw 'ACTUAL_SAVED_SOURCE_ZERO_AFTER_IMPORT'};$result.ok=$true;$result.stage='DONE'}}catch{$result.error=$_.Exception.Message}
finally{if($w){try{$w.Dispose()}catch{}};$result.completedAt=(Get-Date).ToString('o');$result.centralPath=SaveCentral 'AGENT_1.1.105_FAST_RESEARCH_IMPORT_ACTUAL_SOURCE_VERIFY_RESULT.json' $result}
$result | ConvertTo-Json -Depth 80 -Compress
if($result.ok){exit 0}else{exit 2}
